package org.qenherkhopeshef.viewToolKit.demo.text;

import java.awt.Color;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.RenderingHints;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Point2D;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;

import org.qenherkhopeshef.viewToolKit.drawing.element.GraphicalElement;
import org.qenherkhopeshef.viewToolKit.drawing.element.ImageElement;
import org.qenherkhopeshef.viewToolKit.drawing.element.PolylineElement;

/// Pictures generated by program, so that the demo needs no image file.
final class SamplePictures {

	private SamplePictures() {
	}

	/// A small landscape (sky, sun, pyramids), with a variant number.
	static BufferedImage landscape(int variant) {
		int w = 180, h = 110;
		BufferedImage image = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		Color sky = Color.getHSBColor(0.55f + 0.05f * (variant % 4), 0.5f, 0.95f);
		g.setPaint(new GradientPaint(0, 0, sky, 0, h, Color.WHITE));
		g.fillRect(0, 0, w, h);
		g.setColor(new Color(255, 200, 40));
		g.fill(new Ellipse2D.Double(20 + 25 * (variant % 5), 12, 26, 26));
		g.setColor(new Color(225, 190, 120));
		g.fillRect(0, 85, w, 25);
		int[][] pyramids = { { 60, 85, 50 }, { 115, 85, 38 }, { 150, 85, 22 } };
		for (int[] p : pyramids) {
			g.setColor(new Color(205, 160, 90));
			g.fillPolygon(new Polygon(new int[] { p[0] - p[2], p[0], p[0] + p[2] },
					new int[] { p[1], p[1] - p[2], p[1] }, 3));
			g.setColor(new Color(160, 120, 60));
			g.fillPolygon(new Polygon(new int[] { p[0], p[0] + p[2], p[0] + p[2] / 3 },
					new int[] { p[1] - p[2], p[1], p[1] }, 3));
		}
		g.setColor(Color.DARK_GRAY);
		g.drawRect(0, 0, w - 1, h - 1);
		g.dispose();
		return image;
	}

	static GraphicalElement landscapeElement(int variant) {
		return new ImageElement(landscape(variant));
	}

	/// A vector star: shows that any graphical element can be embedded in the
	/// text, not only bitmaps.
	static GraphicalElement star(double size) {
		List<Point2D> points = new ArrayList<>();
		for (int i = 0; i < 10; i++) {
			double angle = -Math.PI / 2 + i * Math.PI / 5;
			double r = (i % 2 == 0 ? 0.5 : 0.2) * size;
			points.add(new Point2D.Double(size / 2 + r * Math.cos(angle), size / 2 + r * Math.sin(angle)));
		}
		PolylineElement star = new PolylineElement(points, true);
		star.setFillColor(new Color(255, 205, 50));
		star.setLineColor(new Color(150, 90, 0));
		star.setLineWidth(1.5);
		return star;
	}
}
